import argparse
import sys
import os
import re
import json
import threading
import concurrent.futures
import urllib.request
import urllib.parse
from html.parser import HTMLParser
import xml.etree.ElementTree as ET
import collections
import ssl

# ANSI Color codes
COLOR_YELLOW = '\033[33m'
COLOR_RED = '\033[31m'
COLOR_GREEN = '\033[32m'
COLOR_RESET = '\033[0m'

class MuffetHTMLParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.links = []

    def handle_starttag(self, tag, attrs):
        attrs_dict = dict(attrs)
        if tag == 'a' and 'href' in attrs_dict:
            self.links.append(attrs_dict['href'])
        elif tag == 'img' and 'src' in attrs_dict:
            self.links.append(attrs_dict['src'])
        elif tag == 'link' and 'href' in attrs_dict:
            self.links.append(attrs_dict['href'])
        elif tag == 'script' and 'src' in attrs_dict:
            self.links.append(attrs_dict['src'])
        elif tag == 'iframe' and 'src' in attrs_dict:
            self.links.append(attrs_dict['src'])
        elif tag == 'source':
            if 'src' in attrs_dict:
                self.links.append(attrs_dict['src'])
            if 'srcset' in attrs_dict:
                for part in attrs_dict['srcset'].split(','):
                    part = part.strip()
                    if part:
                        url = part.split(' ')[0]
                        if url:
                            self.links.append(url)
        elif tag == 'track' and 'src' in attrs_dict:
            self.links.append(attrs_dict['src'])

def parse_status_codes(codes_str):
    accepted = []
    for part in codes_str.split(','):
        if '..' in part:
            try:
                start, end = part.split('..')
                accepted.append((int(start), int(end)))
            except ValueError:
                pass
        else:
            try:
                accepted.append((int(part), int(part) + 1))
            except ValueError:
                pass
    return accepted

def is_accepted_status(code, accepted_ranges):
    for start, end in accepted_ranges:
        if start <= code < end:
            return True
    return False

class Crawler:
    def __init__(self, opts, root_url):
        self.opts = opts
        self.root_url = root_url
        self.root_parsed = urllib.parse.urlparse(root_url)
        self.visited_pages = set()
        self.visited_links = {} # url -> status_or_error
        self.results = collections.defaultdict(list) # page_url -> [ {url, status, error} ]
        self.lock = threading.Lock()
        self.accepted_ranges = parse_status_codes(opts.accepted_status_codes)
        self.executor = concurrent.futures.ThreadPoolExecutor(max_workers=opts.max_connections)
        self.headers = {}
        for h in opts.headers:
            if ':' in h:
                k, v = h.split(':', 1)
                self.headers[k.strip()] = v.strip()

        self.exclude_res = [re.compile(p) for p in opts.exclude]
        self.include_res = [re.compile(p) for p in opts.include]

        self.ssl_context = ssl.create_default_context()
        if opts.skip_tls_verification:
            self.ssl_context.check_hostname = False
            self.ssl_context.verify_mode = ssl.CERT_NONE

    def is_excluded(self, url):
        for r in self.exclude_res:
            if r.search(url):
                return True
        if self.include_res:
            for r in self.include_res:
                if r.search(url):
                    return False
            return True
        return False

    def normalize_url(self, url, base):
        joined = urllib.parse.urljoin(base, url)
        parsed = urllib.parse.urlparse(joined)
        if self.opts.ignore_fragments:
            parsed = parsed._replace(fragment='')
        return parsed.geturl()

    def fetch(self, url):
        req = urllib.request.Request(url, headers=self.headers)
        try:
            with urllib.request.urlopen(req, timeout=self.opts.timeout, context=self.ssl_context) as resp:
                return resp.getcode(), resp.read(), resp.geturl()
        except urllib.error.HTTPError as e:
            return e.code, None, url
        except Exception as e:
            return str(e), None, url

    def check_link(self, url):
        with self.lock:
            if url in self.visited_links:
                return self.visited_links[url]

        # Actually fetch the link (or just HEAD? Muffet seems to do GET because it scrapes)
        # But for external links it only needs to check status.
        # Actually Muffet does GET for everything because it needs to read the body if it's a page to scrape.
        status, _, final_url = self.fetch(url)

        with self.lock:
            self.visited_links[url] = status
            return status

    def crawl(self, url, depth=0):
        url = self.normalize_url(url, self.root_url)

        with self.lock:
            if url in self.visited_pages:
                return
            self.visited_pages.add(url)

        status, body, final_url = self.fetch(url)

        if isinstance(status, str):
            # Error fetching root page
            if depth == 0:
                print(f"failed to fetch root page: {status}")
                sys.exit(1)
            return

        if not is_accepted_status(status, self.accepted_ranges):
             if depth == 0:
                print(f"failed to fetch root page: {status}")
                sys.exit(1)
             return

        if body is None:
            return

        parser = MuffetHTMLParser()
        try:
            parser.feed(body.decode('utf-8', errors='ignore'))
        except:
            return

        links = []
        for l in parser.links:
            abs_l = self.normalize_url(l, final_url)
            if self.is_excluded(abs_l):
                continue
            links.append(abs_l)

        # Check all links
        future_to_url = {self.executor.submit(self.check_link, l): l for l in links}

        page_results = []
        for future in concurrent.futures.as_completed(future_to_url):
            l = future_to_url[future]
            res_status = future.result()
            page_results.append({'url': l, 'status': res_status})

        with self.lock:
            self.results[url] = page_results

        # Recurse if on same host
        if not self.opts.one_page_only:
            for l in links:
                parsed_l = urllib.parse.urlparse(l)
                if parsed_l.netloc == self.root_parsed.netloc:
                    self.crawl(l, depth + 1)

    def run(self):
        self.crawl(self.root_url)
        self.executor.shutdown()

# ... finish main ...
EOF
