class MuffetHTMLParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.links = []

    def handle_starttag(self, tag, attrs):
        attrs_dict = {k: v for k, v in attrs if v is not None}
        if tag == 'a' and 'href' in attrs_dict:
            self.links.append(attrs_dict['href'])
        elif tag == 'img' and 'src' in attrs_dict:
            self.links.append(attrs_dict['src'])
        elif tag == 'link' and 'href' in attrs_dict:
            self.links.append(attrs_dict['href'])
        elif tag == 'script' and 'src' in attrs_dict:
            self.links.append(attrs_dict['src'])
        elif tag == 'iframe' and 'src' in attrs_dict:
            self.links.append(attrs_dict['src'])
        elif tag == 'source':
            if 'src' in attrs_dict:
                self.links.append(attrs_dict['src'])
            if 'srcset' in attrs_dict:
                for part in attrs_dict['srcset'].split(','):
                    part = part.strip()
                    if part:
                        url = part.split(' ')[0]
                        if url:
                            self.links.append(url)
        elif tag == 'track' and 'src' in attrs_dict:
            self.links.append(attrs_dict['src'])

def parse_status_codes(codes_str):
    accepted = []
    for part in codes_str.split(','):
        if '..' in part:
            try:
                start, end = part.split('..')
                accepted.append((int(start), int(end)))
            except ValueError:
                pass
        else:
            try:
                accepted.append((int(part), int(part) + 1))
            except ValueError:
                pass
    return accepted

def is_accepted_status(code, accepted_ranges):
    if not isinstance(code, int):
        return False
    for start, end in accepted_ranges:
        if start <= code < end:
            return True
    return False

class Crawler:
    def __init__(self, opts, root_url):
        self.opts = opts
        # Normalize root_url to have a trailing slash if it's just a domain
        parsed = urllib.parse.urlparse(root_url)
        if not parsed.path:
            root_url += '/'
        self.root_url = root_url
        self.root_parsed = urllib.parse.urlparse(root_url)
        self.visited_pages = set()
        self.visited_links = {} # url -> status
        self.results = collections.OrderedDict() # page_url -> [ {url, status} ]
        self.lock = threading.Lock()
        self.accepted_ranges = parse_status_codes(opts.accepted_status_codes)
        self.headers = {'User-Agent': 'muffet'}
        for h in opts.headers:
            if ':' in h:
                k, v = h.split(':', 1)
                self.headers[k.strip()] = v.strip()

        self.exclude_res = [re.compile(p) for p in opts.exclude]
        self.include_res = [re.compile(p) for p in opts.include]

        self.ssl_context = ssl.create_default_context()
        if opts.skip_tls_verification:
            self.ssl_context.check_hostname = False
            self.ssl_context.verify_mode = ssl.CERT_NONE

        self.robot_parser = None
        if opts.follow_robots_txt:
            self.robot_parser = urllib.robotparser.RobotFileParser()
            self.robot_parser.set_url(urllib.parse.urljoin(root_url, '/robots.txt'))
            try:
                req = urllib.request.Request(self.robot_parser.url, headers=self.headers)
                with urllib.request.urlopen(req, timeout=self.opts.timeout, context=self.ssl_context) as resp:
                    self.robot_parser.parse(resp.read().decode('utf-8', errors='ignore').splitlines())
            except:
                pass

        self.sitemap_pages = None
        if opts.follow_sitemap_xml:
            self.sitemap_pages = self.parse_sitemap(root_url)

    def parse_sitemap(self, url):
        pages = set()
        try:
            req = urllib.request.Request(url, headers=self.headers)
            with urllib.request.urlopen(req, timeout=self.opts.timeout, context=self.ssl_context) as resp:
                content = resp.read()
                # Simple regex to find <loc> contents because XML parsing might fail on large/malformed sitemaps
                locs = re.findall(r'<loc>(.*?)</loc>', content.decode('utf-8', errors='ignore'))
                for loc in locs:
                    pages.add(loc.strip())
        except:
            pass
        return pages

    def is_excluded(self, url):
        for r in self.exclude_res:
            if r.search(url):
                return True
        if self.include_res:
            found = False
            for r in self.include_res:
                if r.search(url):
                    found = True
                    break
            if not found:
                return True
        return False

    def normalize_url(self, url, base):
        joined = urllib.parse.urljoin(base, url)
        parsed = urllib.parse.urlparse(joined)
        if self.opts.ignore_fragments:
            parsed = parsed._replace(fragment='')
        return parsed.geturl()

    def fetch(self, url):
        req = urllib.request.Request(url, headers=self.headers)
        try:
            with urllib.request.urlopen(req, timeout=self.opts.timeout, context=self.ssl_context) as resp:
                return resp.getcode(), resp.read(), resp.geturl()
        except urllib.error.HTTPError as e:
            return e.code, None, url
        except Exception as e:
            msg = str(e)
            if "connection refused" in msg.lower():
                msg = f"dial tcp {urllib.parse.urlparse(url).netloc}: connect: connection refused"
            return f"error when dialing {urllib.parse.urlparse(url).netloc}: {msg}", None, url

    def check_link(self, url):
        with self.lock:
            if url in self.visited_links:
                return self.visited_links[url]

        status, _, _ = self.fetch(url)

        with self.lock:
            self.visited_links[url] = status
            return status

    def run(self):
        if self.opts.follow_sitemap_xml:
            queue = list(self.sitemap_pages) if self.sitemap_pages else []
            # Also add the sitemap itself to results? Muffet did.
            # But the sitemap itself is not "scraped" for links other than <loc>
        else:
            queue = [self.root_url]

        with concurrent.futures.ThreadPoolExecutor(max_workers=self.opts.max_connections) as executor:
            # We use a set for queue to avoid duplicates in the same batch
            to_crawl = collections.deque(queue)

            while to_crawl:
                # To match Muffet's concurrency, we can submit multiple pages at once.
                # Let's take up to max_connections pages.
                batch = []
                while to_crawl and len(batch) < self.opts.max_connections:
                    url = to_crawl.popleft()
                    url = self.normalize_url(url, self.root_url)
                    with self.lock:
                        if url in self.visited_pages:
                            continue
                        self.visited_pages.add(url)
                    batch.append(url)

                if not batch:
                    break

                future_to_page = {executor.submit(self.fetch, url): url for url in batch}
                for future in concurrent.futures.as_completed(future_to_page):
                    page_url = future_to_page[future]
                    status, body, final_url = future.result()

                    # Handle sitemap as a special page
                    if self.opts.follow_sitemap_xml and page_url == self.root_url:
                        # For sitemap, we already parsed it.
                        # But Muffet shows sitemap in results.
                        links = [{'url': p, 'status': 200} for p in sorted(list(self.sitemap_pages))]
                        with self.lock:
                            self.results[page_url] = links
                        continue

                    if isinstance(status, str) or not is_accepted_status(status, self.accepted_ranges):
                        if page_url == self.root_url:
                             print(f"failed to fetch root page: {status}")
                             sys.exit(1)
                        continue

                    if body is None:
                        continue

                    parser = MuffetHTMLParser()
                    try:
                        parser.feed(body.decode('utf-8', errors='ignore'))
                    except:
                        continue

                    found_links = []
                    for l in parser.links:
                        abs_l = self.normalize_url(l, final_url)
                        if self.is_excluded(abs_l):
                            continue
                        found_links.append(abs_l)

                    if not found_links and not self.opts.verbose:
                        continue

                    # Check links
                    # We can use another executor or just submit to the same one.
                    # Muffet seems to check links concurrently.
                    link_futures = {executor.submit(self.check_link, l): l for l in set(found_links)}
                    checked_links = {}
                    for f in concurrent.futures.as_completed(link_futures):
                        l = link_futures[f]
                        checked_links[l] = f.result()

                    page_results = []
                    for l in found_links:
                        page_results.append({'url': l, 'status': checked_links[l]})

                    with self.lock:
                        self.results[page_url] = page_results

                    # Add same-host links to queue if not one-page-only
                    if not self.opts.one_page_only:
                        for l in set(found_links):
                            parsed_l = urllib.parse.urlparse(l)
                            if parsed_l.netloc == self.root_parsed.netloc:
                                if self.sitemap_pages is not None:
                                    # If sitemap is used, we only scrape pages in sitemap.
                                    # Those are already in to_crawl or visited.
                                    pass
                                elif self.robot_parser:
                                    if self.robot_parser.can_fetch('muffet', l):
                                        to_crawl.append(l)
                                else:
                                    to_crawl.append(l)

    def print_results(self):
        has_broken = False
        color_enabled = False
        if self.opts.color == 'always':
            color_enabled = True
        elif self.opts.color == 'auto':
            color_enabled = sys.stdout.isatty()

        # Check for any broken links first to set has_broken
        for page_url, links in self.results.items():
            for l in links:
                if not is_accepted_status(l['status'], self.accepted_ranges):
                    has_broken = True

        if self.opts.format == 'json' or self.opts.json:
            output = []
            for page_url in self.results:
                links = self.results[page_url]
                links_output = []
                for l in links:
                    is_ok = is_accepted_status(l['status'], self.accepted_ranges)
                    if not is_ok or self.opts.verbose or self.opts.experimental_verbose_json:
                        err = "" if is_ok else str(l['status'])
                        links_output.append({'url': l['url'], 'error': err})
                if links_output:
                    output.append({'url': page_url, 'links': links_output})
            print(json.dumps(output, separators=(',', ':')))
            return has_broken

        if self.opts.format == 'junit' or self.opts.junit:
            root = ET.Element('testsuites')
            for page_url in self.results:
                links = self.results[page_url]
                suite = ET.SubElement(root, 'testsuite', name=page_url, tests=str(len(links)), failures=str(sum(1 for l in links if not is_accepted_status(l['status'], self.accepted_ranges))), skipped='0')
                for l in links:
                    case = ET.SubElement(suite, 'testcase', name=l['url'], classname=page_url)
                    if not is_accepted_status(l['status'], self.accepted_ranges):
                        ET.SubElement(case, 'failure', message=str(l['status']))

            xml_str = ET.tostring(root, encoding='utf-8')
            print('<?xml version="1.0" encoding="UTF-8"?>')
            print(xml_str.decode('utf-8'))
            return has_broken

        # Text format
        for page_url, links in self.results.items():
            page_broken = [l for l in links if not is_accepted_status(l['status'], self.accepted_ranges)]
            if page_broken or self.opts.verbose:
                if color_enabled:
                    sys.stdout.write(f"{COLOR_YELLOW}{page_url}{COLOR_RESET}\n")
                else:
                    sys.stdout.write(f"{page_url}\n")

                for l in links:
                    is_ok = is_accepted_status(l['status'], self.accepted_ranges)
                    if not is_ok or self.opts.verbose:
                        status_str = str(l['status'])
                        if color_enabled:
                            color = COLOR_GREEN if is_ok else COLOR_RED
                            sys.stdout.write(f"\t{color}{status_str}{COLOR_RESET}\t{l['url']}\n")
                        else:
                            sys.stdout.write(f"\t{status_str}\t{l['url']}\n")
        return has_broken

def main():
    parser = argparse.ArgumentParser(add_help=False)
    parser.add_argument('--accepted-status-codes', default='200..300')
    parser.add_argument('-b', '--buffer-size', type=int, default=4096)
    parser.add_argument('-c', '--max-connections', type=int, default=512)
    parser.add_argument('--max-connections-per-host', type=int, default=512)
    parser.add_argument('--max-response-body-size', type=int, default=10000000)
    parser.add_argument('-e', '--exclude', action='append', default=[])
    parser.add_argument('-i', '--include', action='append', default=[])
    parser.add_argument('--follow-robots-txt', action='store_true')
    parser.add_argument('--follow-sitemap-xml', action='store_true')
    parser.add_argument('--header', action='append', dest='headers', default=[])
    parser.add_argument('-f', '--ignore-fragments', action='store_true')
    parser.add_argument('--max-retries', type=int, default=0)
    parser.add_argument('--dns-resolver')
    parser.add_argument('--format', choices=['text', 'json', 'junit'], default='text')
    parser.add_argument('--json', action='store_true')
    parser.add_argument('--experimental-verbose-json', action='store_true')
    parser.add_argument('--junit', action='store_true')
    parser.add_argument('-r', '--max-redirections', type=int, default=64)
    parser.add_argument('--rate-limit', type=int)
    parser.add_argument('-t', '--timeout', type=int, default=10)
    parser.add_argument('-v', '--verbose', action='store_true')
    parser.add_argument('--proxy')
    parser.add_argument('--skip-tls-verification', action='store_true')
    parser.add_argument('--one-page-only', action='store_true')
    parser.add_argument('--color', choices=['auto', 'always', 'never'], default='auto')
    parser.add_argument('--version', action='store_true')
    parser.add_argument('-h', '--help', action='store_true')
    parser.add_argument('url', nargs='?')

    args = parser.parse_args()

    if args.help:
        print("""Usage:
  executable [options] <url>

Application Options:
      --accepted-status-codes=<codes>       Accepted HTTP response status codes
                                            (e.g. '200..300,403') (default:
                                            200..300)
  -b, --buffer-size=<size>                  HTTP response buffer size in bytes
                                            (default: 4096)
  -c, --max-connections=<count>             Maximum number of HTTP connections
                                            (default: 512)
      --max-connections-per-host=<count>    Maximum number of HTTP connections
                                            per host (default: 512)
      --max-response-body-size=<size>       Maximum response body size to read
                                            (default: 10000000)
  -e, --exclude=<pattern>...                Exclude URLs matched with given
                                            regular expressions
  -i, --include=<pattern>...                Include URLs matched with given
                                            regular expressions
      --follow-robots-txt                   Follow robots.txt when scraping
                                            pages
      --follow-sitemap-xml                  Scrape only pages listed in
                                            sitemap.xml (deprecated)
      --header=<header>...                  Custom headers
  -f, --ignore-fragments                    Ignore URL fragments
      --max-retries=<count>                 Maximum retry count for network
                                            errors (default: 0)
      --dns-resolver=<address>              Custom DNS resolver
      --format=[text|json|junit]            Output format (default: text)
      --json                                Output results in JSON (deprecated)
      --experimental-verbose-json           Include successful results in JSON
                                            (deprecated)
      --junit                               Output results as JUnit XML file
                                            (deprecated)
  -r, --max-redirections=<count>            Maximum number of redirections
                                            (default: 64)
      --rate-limit=<rate>                   Max requests per second
  -t, --timeout=<seconds>                   Timeout for HTTP requests in
                                            seconds (default: 10)
  -v, --verbose                             Show successful results too
      --proxy=<host>                        HTTP proxy host
      --skip-tls-verification               Skip TLS certificate verification
      --one-page-only                       Only check links found in the given
                                            URL
      --color=[auto|always|never]           Color output (default: auto)
  -h, --help                                Show this help
      --version                             Show version""")
        sys.exit(0)

    if args.version:
        print("2.11.1")
        sys.exit(0)

    if not args.url:
        print("Usage:\n  executable [options] <url>")
        sys.exit(1)

    crawler = Crawler(args, args.url)
    crawler.run()
    has_broken = crawler.print_results()

    if has_broken:
        sys.exit(1)
    else:
        sys.exit(0)

if __name__ == '__main__':
    main()
